            } else if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, ENTRY_DATE, date.toString()));
            } else {
                setting.setValue(date.toString());
                settings.saveAndFlush(setting);
            }
        } catch (DataIntegrityViolationException raced) {
