340	      this.gradeTermsFromForm.markAsUntouched();
341	      this.gradeGraceForm.markAsPristine();
342	      this.gradeGraceForm.markAsUntouched();
343	      this.gradeGraceFromForm.markAsPristine();
344	      this.gradeGraceFromForm.markAsUntouched();
345	      this.gradeProofThresholdForm.markAsPristine();
346	      this.gradeProofThresholdForm.markAsUntouched();
347	      this.gradeProofThresholdFromForm.markAsPristine();
348	      this.gradeProofThresholdFromForm.markAsUntouched();
349	      this.permissionsForm.markAsPristine();
350	      this.permissionsForm.markAsUntouched();
351	      if (sheet) void this.reload(sheet.id);
352	    });
353	  }
354	
355	  private async reload(sheetId: string): Promise<void> {
356	    try {
357	      const settings = await this.api.get(sheetId);
358	      if (this.session.sheet()?.id === sheetId) this.show(settings);
359	    } catch {
360	      this.settingsError.set('The settings could not be loaded.');
361	    }
362	  }
363	
364	  protected async saveSettings(): Promise<void> {
365	    // A second submit before the first has answered is ignored, so it stores one change, not two.
366	    if (this.savingSettings()) return;
367	    const sheet = this.session.sheet();
368	    if (!sheet) return;
369	    this.settingsError.set('');
370	    const { clerkLimit, clerkLimitFrom, floor, floorFrom, terms, termsFrom, latePct, latePctFrom, policyDate,
371	      periodNumberingFrom, cap, capFrom, proofThreshold, proofThresholdFrom,
372	      noteThreshold, noteThresholdFrom, graceDays, entryDate } = this.settingsForm.controls;
373	    // A dated setting is saved when its value or its from-date was changed; the from-date checked first.
374	    const froms = [
375	      { label: 'clerk limit', control: clerkLimitFrom }, { label: 'floor', control: floorFrom },
376	      { label: 'terms', control: termsFrom }, { label: 'late percent', control: latePctFrom },
377	      { label: 'cap', control: capFrom }, { label: 'proof threshold', control: proofThresholdFrom },
378	      { label: 'note threshold', control: noteThresholdFrom },
379	      ...GRADES.map((g) => ({ label: `terms of grade ${g}`, control: this.gradeTermsFromForm.controls[g] })),
380	      ...GRADES.map((g) => ({ label: `grace of grade ${g}`, control: this.gradeGraceFromForm.controls[g] })),
381	      ...GRADES.map((g) => ({ label: `proof threshold of grade ${g}`, control: this.gradeProofThresholdFromForm.controls[g] })),
382	    ];
383	    for (const { label, control } of froms) {
384	      const from = control.value.trim();
385	      if (from !== '' && !isDate(from)) {
386	        this.settingsError.set(`Type the date the ${label} is from as yyyy-mm-dd, or leave it blank for the sheet's today.`);
387	        return;
388	      }
389	    }
390	    const fromOf = (control: AbstractControl<string>): string | null => control.value.trim() === '' ? null : control.value.trim();
391	    const dirty = (value: AbstractControl, from: AbstractControl): boolean => changed(value) || changed(from);
392	    const limit = clerkLimit.value.trim();
393	    const floorValue = floor.value.trim();
394	    const termsValue = terms.value.trim();
395	    const latePctValue = latePct.value.trim();
396	    const policyDateValue = policyDate.value.trim();
397	    const periodNumberingFromValue = periodNumberingFrom.value.trim();
398	    const capValue = cap.value.trim();
399	    const proofThresholdValue = proofThreshold.value.trim();
400	    const noteThresholdValue = noteThreshold.value.trim();
401	    const graceDaysValue = graceDays.value.trim();
402	    const entryDateValue = entryDate.value.trim();
403	    if (dirty(clerkLimit, clerkLimitFrom) && limit !== '' && !MONEY.test(limit)) {
404	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
405	      return;
406	    }
407	    if (dirty(floor, floorFrom) && !MONEY.test(floorValue)) {
408	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
409	      return;
410	    }
