412	      this.settingsError.set('Type terms as a whole number of business days, from 0 to 36500.');
413	      return;
414	    }
415	    const gradeTermsValues = GRADES.map((g) => ({ grade: g, control: this.gradeTermsForm.controls[g],
416	      from: this.gradeTermsFromForm.controls[g], value: this.gradeTermsForm.controls[g].value.trim() }));
417	    for (const { grade, control, from, value } of gradeTermsValues) {
418	      if (dirty(control, from) && value !== '' && (!DAYS.test(value) || Number(value) > 36500)) {
419	        this.settingsError.set(`Type the terms of grade ${grade} as a whole number of business days, from 0 to 36500, or leave them blank for the sheet's terms.`);
420	        return;
421	      }
422	    }
423	    const gradeGraceValues = GRADES.map((g) => ({ grade: g, control: this.gradeGraceForm.controls[g],
424	      from: this.gradeGraceFromForm.controls[g], value: this.gradeGraceForm.controls[g].value.trim() }));
425	    for (const { grade, control, from, value } of gradeGraceValues) {
426	      if (dirty(control, from) && value !== '' && (!DAYS.test(value) || Number(value) > 36500)) {
427	        this.settingsError.set(`Type the grace of grade ${grade} as a whole number of days, from 0 to 36500, or leave it blank for none.`);
428	        return;
429	      }
430	    }
