439	    if (changed(periodNumberingFrom) && periodNumberingFromValue !== '' && !isDate(periodNumberingFromValue)) {
440	      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank for sheet-wide numbering.');
441	      return;
442	    }
443	    if (dirty(cap, capFrom) && capValue !== '' && !MONEY.test(capValue)) {
444	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank for no cap.');
445	      return;
446	    }
447	    if (dirty(proofThreshold, proofThresholdFrom) && proofThresholdValue !== '' && !MONEY.test(proofThresholdValue)) {
448	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
449	      return;
450	    }
451	    const gradeProofThresholdValues = GRADES.map((g) => ({ grade: g, control: this.gradeProofThresholdForm.controls[g],
452	      from: this.gradeProofThresholdFromForm.controls[g], value: this.gradeProofThresholdForm.controls[g].value.trim() }));
453	    for (const { grade, control, from, value } of gradeProofThresholdValues) {
454	      if (dirty(control, from) && value !== '' && !MONEY.test(value)) {
455	        this.settingsError.set(`Type the proof threshold of grade ${grade} as 0.00 or more, with up to two decimals, or leave it blank for the sheet's.`);
456	        return;
457	      }
458	    }
459	    if (dirty(noteThreshold, noteThresholdFrom) && noteThresholdValue !== '' && !MONEY.test(noteThresholdValue)) {
460	      this.settingsError.set('Type a note threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
461	      return;
462	    }
463	    if (changed(graceDays) && graceDaysValue !== '' && (!DAYS.test(graceDaysValue) || Number(graceDaysValue) > 36500)) {
464	      this.settingsError.set('Type grace days as a whole number of business days, from 0 to 36500, or leave them blank for off.');
465	      return;
466	    }
467	    if (changed(entryDate) && entryDateValue !== '' && !isDate(entryDateValue)) {
468	      this.settingsError.set('Type an entry date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
469	      return;
470	    }
471	    const permissionValues = PERMISSION_ACTIONS.map((a) => ({ action: a, control: this.permissionsForm.controls[a],
472	      value: this.permissionsForm.controls[a].value.split(',').map((r) => r.trim()).join(',') }));
473	    for (const { action, control, value } of permissionValues) {
474	      if (changed(control) && value !== '' && !value.split(',').every((r) => ROLES.includes(r as Role))) {
475	        this.settingsError.set(`Name who may ${action} as a comma separated list of clerk, steward and viewer, or leave it blank for the standing rule.`);
476	        return;
477	      }
478	    }
479	    this.savingSettings.set(true);
480	    try {
481	      if (dirty(clerkLimit, clerkLimitFrom)) {
482	        const settings = await this.api.setClerkLimit(sheet.id, limit === '' ? null : limit, fromOf(clerkLimitFrom));
483	        settled(clerkLimit);
484	        settled(clerkLimitFrom);
485	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
486	      }
487	      if (dirty(floor, floorFrom)) {
488	        const settings = await this.api.setFloor(sheet.id, floorValue, fromOf(floorFrom));
489	        settled(floor);
490	        settled(floorFrom);
491	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
492	      }
493	      if (dirty(terms, termsFrom)) {
494	        const settings = await this.api.setTerms(sheet.id, Number(termsValue), fromOf(termsFrom));
495	        settled(terms);
496	        settled(termsFrom);
497	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
498	      }
499	      for (const { grade, control, from, value } of gradeTermsValues) {
500	        if (!dirty(control, from)) continue;
501	        const settings = await this.api.setGradeTerms(sheet.id, grade, value === '' ? null : Number(value), fromOf(from));
502	        settled(control);
503	        settled(from);
504	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
505	      }
506	      if (dirty(latePct, latePctFrom)) {
507	        const settings = await this.api.setLatePct(sheet.id, latePctValue, fromOf(latePctFrom));
508	        settled(latePct);
509	        settled(latePctFrom);
510	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
511	      }
512	      for (const { grade, control, from, value } of gradeGraceValues) {
513	        if (!dirty(control, from)) continue;
514	        const settings = await this.api.setGradeGrace(sheet.id, grade, value === '' ? null : Number(value), fromOf(from));
515	        settled(control);
516	        settled(from);
517	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
518	      }
519	      if (changed(policyDate)) {
520	        const settings = await this.api.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue);
521	        settled(policyDate);
522	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
523	      }
524	      if (changed(periodNumberingFrom)) {
525	        const settings = await this.api.setPeriodNumberingFrom(sheet.id, periodNumberingFromValue === '' ? null : periodNumberingFromValue);
526	        settled(periodNumberingFrom);
527	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
528	      }
529	      if (dirty(cap, capFrom)) {
530	        const settings = await this.api.setCap(sheet.id, capValue === '' ? null : capValue, fromOf(capFrom));
531	        settled(cap);
532	        settled(capFrom);
533	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
534	      }
535	      if (dirty(proofThreshold, proofThresholdFrom)) {
536	        const settings = await this.api.setProofThreshold(sheet.id, proofThresholdValue === '' ? null : proofThresholdValue,
537	          fromOf(proofThresholdFrom));
538	        settled(proofThreshold);
539	        settled(proofThresholdFrom);
540	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
541	      }
542	      for (const { grade, control, from, value } of gradeProofThresholdValues) {
543	        if (!dirty(control, from)) continue;
544	        const settings = await this.api.setGradeProofThreshold(sheet.id, grade, value === '' ? null : value, fromOf(from));
545	        settled(control);
546	        settled(from);
547	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
548	      }
549	      if (dirty(noteThreshold, noteThresholdFrom)) {
550	        const settings = await this.api.setNoteThreshold(sheet.id, noteThresholdValue === '' ? null : noteThresholdValue,
551	          fromOf(noteThresholdFrom));
552	        settled(noteThreshold);
553	        settled(noteThresholdFrom);
554	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
555	      }
556	      if (changed(graceDays)) {
557	        const settings = await this.api.setGraceDays(sheet.id, graceDaysValue === '' ? null : Number(graceDaysValue));
558	        settled(graceDays);
559	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
560	      }
561	      if (changed(entryDate)) {
562	        const settings = await this.api.setEntryDate(sheet.id, entryDateValue === '' ? null : entryDateValue);
563	        settled(entryDate);
564	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
565	      }
566	      for (const { action, control, value } of permissionValues) {
567	        if (!changed(control)) continue;
568	        const settings = await this.api.setPermission(sheet.id, action, value);
569	        settled(control);
570	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
571	      }
572	    } catch {
573	      this.settingsError.set('The settings could not be saved.');
574	    } finally {
575	      this.savingSettings.set(false);
576	    }
577	  }
578	
579	  /** The terms in force for a grade on the sheet's today: its own, else the sheet's. */
580	  protected gradeTermsNow(grade: Grade): number {
581	    const own = this.now(`terms-${grade}`);
582	    return own === null ? this.terms() : Number(own);
583	  }
584	
585	  /** Show the settings as the store answered them, and share the dated floor, late percent, cap and grades' grace, and
586	   *  the policy date, with the screens showing them. */
587	  private show(settings: SettingsView): void {
588	    this.dated.set(settings.dated);
589	    this.sheetFloor.history.set(settings.dated['floor'] ?? []);
590	    this.sheetLatePct.history.set(settings.dated['late-pct'] ?? []);
591	    this.sheetCap.history.set(settings.dated['cap'] ?? []);
592	    this.sheetGrace.history.set(Object.fromEntries(GRADES.map((g) => [g, settings.dated[`grace-${g}`] ?? []])));
593	    this.policyDate.set(settings.policyDate);
594	    this.sheetPolicyDate.date.set(settings.policyDate);
595	    this.periodNumberingFrom.set(settings.periodNumberingFrom);
596	    this.assigned.set(settings.roles);
597	    this.permissions.set(settings.permissions);
598	    this.graceDays.set(settings.graceDays);
599	    this.entryDate.set(settings.entryDate);
600	    this.delegations.set(settings.delegations);
601	  }
602	
603	  protected async saveRole(): Promise<void> {
604	    if (this.savingRole()) return;
605	    const sheet = this.session.sheet();
606	    if (!sheet) return;
607	    this.roleError.set('');
608	    const user = this.roleForm.getRawValue().user.trim();
609	    const role = this.roleForm.getRawValue().role.trim();
610	    if (user === '') {
611	      this.roleError.set('Type the user name to assign a role to.');
612	      return;
613	    }
614	    if (!ROLES.includes(role as Role)) {
615	      this.roleError.set('Choose a role of clerk, steward or viewer.');
616	      return;
617	    }
618	    this.savingRole.set(true);
619	    try {
620	      const saved = await this.api.setRole(sheet.id, user, role as Role);
621	      if (this.session.sheet()?.id === sheet.id) {
622	        this.assigned.update((list) =>
623	          [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)));
624	      }
625	    } catch {
626	      this.roleError.set('The role could not be assigned.');
627	    } finally {
628	      this.savingRole.set(false);
629	    }
630	  }
631	
632	  protected async saveDelegation(): Promise<void> {
633	    if (this.savingDelegation()) return;
634	    const sheet = this.session.sheet();
635	    if (!sheet) return;
636	    this.delegateError.set('');
637	    const { user, from, to } = this.delegateForm.getRawValue();
638	    const name = user.trim();
639	    const start = from.trim();
640	    const end = to.trim();
641	    if (name === '') {
642	      this.delegateError.set('Type the user name to delegate the steward role to.');
643	      return;
644	    }
645	    if ((start !== '' && !isDate(start)) || !isDate(end)) {
646	      this.delegateError.set('Type the dates as yyyy-mm-dd.');
647	      return;
648	    }
649	    if (end < (start === '' ? sheet.today : start)) {
650	      this.delegateError.set('The to-date cannot be before the from-date.');
651	      return;
652	    }
653	    this.savingDelegation.set(true);
654	    try {
655	      const saved = await this.api.delegate(sheet.id, name, start === '' ? null : start, end);
656	      if (this.session.sheet()?.id === sheet.id) this.delegations.update((list) => [...list, saved]);
657	    } catch {
658	      this.delegateError.set('Only a steward can delegate the steward role.');
659	    } finally {
660	      this.savingDelegation.set(false);
661	    }
662	  }
