375	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + GRACE_DAYS
376	                + " value=" + (days == null ? "" : days.toString()));
377	        return days;
378	    }
379	
380	    /** The cap in force on the sheet's today, with two decimals, or null when there is no cap. */
381	    @Transactional(readOnly = true)
382	    public BigDecimal cap(String sheetId) {
383	        return dated(sheetId).capOn(sheets.today(sheetId));
384	    }
385	
386	    /** A person's due-total held to the cap: the cap when it is above it; n/a (null) and no cap leave it as it is. */
387	    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
388	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
389	    }
390	
391	    /** Record the sheet's cap, kept to two decimals, from a date; null clears it from then, leaving no
392	     *  cap. The due-totals it moves are audited after it. */
393	    @Transactional
394	    public BigDecimal setCap(String sheetId, String user, BigDecimal cap, LocalDate from) {
395	        BigDecimal value = cap == null ? null : cap.setScale(2);
396	        Rollup.Snapshot before = rollup.snapshot(sheetId);
397	        record(sheetId, user, CAP, value == null ? "" : value.toPlainString(), from);
398	        rollup.recordChanges(user, before);
399	        return value;
400	    }
401	
402	    /** The clerk limit in force on the sheet's today, with two decimals, or null when there is no limit. */
403	    @Transactional(readOnly = true)
404	    public BigDecimal clerkLimit(String sheetId) {
405	        return dated(sheetId).clerkLimitOn(sheets.today(sheetId));
406	    }
407	
408	    /** Record the sheet's clerk limit, kept to two decimals, from a date; null clears it from then,
409	     *  leaving no limit. */
410	    @Transactional
411	    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
412	        BigDecimal value = limit == null ? null : limit.setScale(2);
413	        record(sheetId, user, CLERK_LIMIT, value == null ? "" : value.toPlainString(), from);
414	        return value;
415	    }
416	
417	    /** The proof threshold in force on the date, with two decimals, or null when there is none. */
418	    @Transactional(readOnly = true)
419	    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
420	        return dated(sheetId).proofThresholdOn(date);
421	    }
422	
423	    /** The proof threshold of a grade in force on the date: its own when set then, else the sheet's; null
424	     *  when there is none. */
425	    @Transactional(readOnly = true)
426	    public BigDecimal proofThreshold(String sheetId, Grade grade, LocalDate date) {
427	        return dated(sheetId).proofThresholdOn(grade, date);
428	    }
429	
430	    /** The key of a grade's own proof threshold. */
431	    public static String proofThresholdKey(Grade grade) {
432	        return PROOF_THRESHOLD + "-" + grade.name();
433	    }
434	
435	    /** Record a grade's own proof threshold, kept to two decimals, from a date; null clears it from then,
436	     *  leaving the sheet's. */
437	    @Transactional
438	    public BigDecimal setGradeProofThreshold(String sheetId, String user, Grade grade, BigDecimal threshold,
439	            LocalDate from) {
440	        BigDecimal value = threshold == null ? null : threshold.setScale(2);
441	        record(sheetId, user, proofThresholdKey(grade), value == null ? "" : value.toPlainString(), from);
442	        return value;
443	    }
444	
445	    /** Record the sheet's proof threshold, kept to two decimals, from a date; null clears it from then. */
446	    @Transactional
447	    public BigDecimal setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
448	        BigDecimal value = threshold == null ? null : threshold.setScale(2);
449	        record(sheetId, user, PROOF_THRESHOLD, value == null ? "" : value.toPlainString(), from);
450	        return value;
451	    }
452	
453	    /** The note threshold in force on the date, with two decimals, or null when there is none. */
454	    @Transactional(readOnly = true)
455	    public BigDecimal noteThreshold(String sheetId, LocalDate date) {
456	        return dated(sheetId).noteThresholdOn(date);
457	    }
458	
459	    /** Record the sheet's note threshold, kept to two decimals, from a date; null clears it from then. */
460	    @Transactional
461	    public BigDecimal setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
462	        BigDecimal value = threshold == null ? null : threshold.setScale(2);
463	        record(sheetId, user, NOTE_THRESHOLD, value == null ? "" : value.toPlainString(), from);
464	        return value;
465	    }
466	
467	    /** The key of an action's permission. */
468	    public static String permissionKey(String action) {
469	        return "perm-" + action;
470	    }
471	
472	    /** The roles each action's permission names, by action, as the sheet set them (comma separated);
473	     *  blank when it keeps the standing rule. */
474	    @Transactional(readOnly = true)
475	    public Map<String, String> permissions(String sheetId) {
476	        Map<String, String> permissions = new LinkedHashMap<>();
477	        for (String action : PERMISSION_ACTIONS) {
478	            permissions.put(action, settings.findBySheetIdAndKey(sheetId, permissionKey(action))
479	                    .map(SheetSetting::getValue).orElse(""));
480	        }
481	        return permissions;
482	    }
483	
484	    /** Refuse an action the user's role is not allowed by the sheet's permission matrix (a blank
485	     *  permission keeps the standing rule), with the action's usual error. */
486	    @Transactional(readOnly = true)
487	    public void refuseUnlessPermitted(String sheetId, String user, String action, String refusal) {
488	        String value = settings.findBySheetIdAndKey(sheetId, permissionKey(action)).map(SheetSetting::getValue)
489	                .orElse("");
490	        Set<Role> allowed = value.isBlank() ? STANDING_PERMISSIONS.get(action) : rolesOf(value);
491	        if (!allowed.contains(roleOf(sheetId, user))) {
492	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, refusal);
493	        }
494	    }
495	
496	    /** The roles a comma separated list names; refused when one of them is not a role. */
497	    private static Set<Role> rolesOf(String value) {
498	        Set<Role> roles = EnumSet.noneOf(Role.class);
499	        for (String label : value.split(",")) {
500	            roles.add(Role.of(label.trim()).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
501	                    "Name the roles as a comma separated list of clerk and steward.")));
502	        }
503	        return roles;
504	    }
505	
506	    /** Set the roles that may take an action, as a comma separated list; blank clears it, keeping the
507	     *  standing rule. Not dated. */
508	    @Transactional
509	    public String setPermission(String sheetId, String user, String action, String roles) {
510	        if (!PERMISSION_ACTIONS.contains(action)) {
511	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "No such action.");
512	        }
513	        String value = roles == null || roles.isBlank() ? ""
514	                : String.join(",", Arrays.stream(roles.split(",")).map(String::trim).toList());
515	        if (!value.isEmpty()) rolesOf(value);
516	        sheets.load(sheetId);
517	        String key = permissionKey(action);
518	        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, key).orElse(null);
519	        try {
520	            if (value.isEmpty()) {
521	                if (setting != null) {
522	                    settings.delete(setting);
523	                    settings.flush();
524	                }
525	            } else if (setting == null) {
526	                settings.saveAndFlush(new SheetSetting(sheetId, key, value));
527	            } else {
528	                setting.setValue(value);
529	                settings.saveAndFlush(setting);
530	            }
531	        } catch (DataIntegrityViolationException raced) {
532	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The setting was changed by someone else.");
533	        }
534	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value);
535	        return value;
536	    }
537	
538	    /** The roles the sheet has assigned, by user name; any other name is a clerk. */
539	    @Transactional(readOnly = true)
540	    public List<SheetRole> roles(String sheetId) {
541	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
542	    }
543	
544	    /** The role the user name acts in on the sheet: a steward while a delegation to it covers the
545	     *  sheet's today, otherwise the one it was assigned (a clerk unless it was assigned another). */
546	    @Transactional(readOnly = true)
547	    public Role roleOf(String sheetId, String user) {
548	        return delegationOn(sheetId, user).isPresent() ? Role.STEWARD : assignedRoleOf(sheetId, user);
549	    }
550	
551	    /** The role the sheet assigned a user name, leaving out any delegation: a clerk unless assigned another. */
552	    @Transactional(readOnly = true)
553	    public Role assignedRoleOf(String sheetId, String user) {
554	        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
555	    }
556	
557	    /** The steward the user acts for while a delegation to it covers the sheet's today; the latest
558	     *  made when more than one does. */
559	    @Override
560	    @Transactional(readOnly = true)
561	    public Optional<String> actingFor(String sheetId, String user) {
562	        return delegationOn(sheetId, user).map(Delegation::getDelegatedBy);
563	    }
564	
565	    private Optional<Delegation> delegationOn(String sheetId, String user) {
566	        List<Delegation> made = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, user);
567	        if (made.isEmpty()) return Optional.empty();
568	        LocalDate today = sheets.today(sheetId);
569	        return made.stream().filter((d) -> d.covers(today)).findFirst();
570	    }
571	
572	    /** The sheet's delegations in the order they were made. */
573	    @Transactional(readOnly = true)
574	    public List<Delegation> delegations(String sheetId) {
575	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
576	    }
577	
578	    /** Delegate the steward role to a user name from a date to a date, inclusive (blank from: the
579	     *  sheet's today); refused to anyone the sheet did not assign the steward role, and when the
580	     *  to-date is before the from-date. */
581	    @Transactional
582	    public Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
583	        sheets.load(sheetId);
584	        if (assignedRoleOf(sheetId, user) != Role.STEWARD) {
585	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can delegate the steward role.");
586	        }
587	        LocalDate start = from != null ? from : sheets.today(sheetId);
588	        LocalDate end = to != null ? to : start;
589	        if (end.isBefore(start)) {
590	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
591	        }
592	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, start, end, user));
593	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + userName + " from=" + start
594	                + " to=" + end);
595	        return saved;
596	    }
597	
598	    /** Assign a user name a role on the sheet, replacing the one it had. */
599	    @Transactional
600	    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
601	        sheets.load(sheetId);
602	        SheetRole assigned = roles.findBySheetIdAndUserName(sheetId, userName).orElse(null);
603	        if (assigned == null) {
604	            assigned = new SheetRole(sheetId, userName, role);
605	        } else {
606	            assigned.setRole(role);
607	        }
608	        SheetRole saved;
609	        try {
610	            saved = roles.saveAndFlush(assigned);
611	        } catch (DataIntegrityViolationException raced) {
612	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The role was changed by someone else.");
613	        }
614	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName
615	                + " role=" + role.label());
616	        return saved;
617	    }
618	}
