318	    /** The settings in force on the sheet's today, with every dated value recorded. */
319	    private SettingsView view(String sheetId) {
320	        LocalDate today = service.today(sheetId);
321	        DatedSettings dated = service.dated(sheetId);
322	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
323	        for (Grade grade : Grade.values()) {
324	            Integer own = dated.gradeTermsOn(grade, today);
325	            if (own != null) gradeTerms.put(grade.name(), own);
326	        }
327	        Map<String, List<DatedView>> history = new LinkedHashMap<>();
328	        for (String key : dated.keys()) {
329	            history.put(key, dated.history(key).stream().map((s) -> new DatedView(s.getFrom(), s.getValue())).toList());
330	        }
331	        return new SettingsView(text(dated.clerkLimitOn(today)), dated.floorOn(today).toPlainString(),
332	                dated.termsOn(today), dated.latePctOn(today).toPlainString(), service.policyDate(sheetId),
333	                service.roles(sheetId).stream().map(RoleView::of).toList(), service.periodNumberingFrom(sheetId),
334	                gradeTerms, text(dated.capOn(today)), history, text(dated.proofThresholdOn(today)),
335	                service.permissions(sheetId), service.graceDays(sheetId),
336	                service.delegations(sheetId).stream().map(DelegationView::of).toList(),
337	                text(dated.noteThresholdOn(today)), service.entryDate(sheetId));
338	    }
